CREATE OR REPLACE FUNCTION public.request_storia_development(_id uuid,_withdraw boolean DEFAULT false,_confirmed uuid[] DEFAULT '{}') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.developments; c uuid; BEGIN
 IF NOT public.can_access_development(_id,true) THEN RAISE EXCEPTION 'Acces refuzat'; END IF;
 SELECT * INTO d FROM public.developments WHERE id=_id FOR UPDATE;
 SELECT id INTO c FROM public.portal_connections WHERE organization_id=d.organization_id AND portal='storia_developer' AND portal_credentials_encrypted IS NOT NULL AND status='connected';
 IF c IS NULL THEN RAISE EXCEPTION 'Conectează contul dezvoltator Storia pentru ansambluri.'; END IF;
 IF NOT _withdraw AND (d.status<>'active' OR d.deleted_at IS NOT NULL) THEN RAISE EXCEPTION 'Ansamblul trebuie să fie activ.'; END IF;
 IF NOT _withdraw AND EXISTS(SELECT 1 FROM public.properties p JOIN public.portal_publications pp ON pp.property_id=p.id AND pp.portal_key='storia' AND pp.enabled JOIN public.portal_listings l ON l.property_id=p.id AND l.portal='storia' WHERE p.development_id=_id AND l.external_id IS NOT NULL AND NOT(p.id=ANY(_confirmed)) AND NOT EXISTS(SELECT 1 FROM public.storia_development_units u WHERE u.property_id=p.id AND u.external_uuid IS NOT NULL)) THEN RAISE EXCEPTION 'Confirmă mutarea anunțurilor de pe contul agenției.'; END IF;
 INSERT INTO public.development_portal_publications(development_id,organization_id,connection_id,desired_active,confirmed_property_ids) VALUES(_id,d.organization_id,c,NOT _withdraw,_confirmed) ON CONFLICT(development_id,portal) DO UPDATE SET desired_active=NOT _withdraw,confirmed_property_ids=_confirmed,updated_at=now();
 PERFORM public.queue_storia_development(_id,CASE WHEN _withdraw THEN 'withdraw' ELSE 'publish' END,auth.uid());END $$;
CREATE OR REPLACE FUNCTION public.claim_storia_development_job() RETURNS SETOF public.storia_development_jobs LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 UPDATE public.storia_development_jobs SET status='error',last_error='Operațiune întreruptă; verifică notificarea Storia înainte de retrimitere.',updated_at=now() WHERE status='running' AND updated_at<now()-interval '5 minutes';
 RETURN QUERY UPDATE public.storia_development_jobs SET status='running',updated_at=now() WHERE id=(SELECT j.id FROM public.storia_development_jobs j WHERE j.status='queued' AND NOT EXISTS(SELECT 1 FROM public.storia_development_jobs r WHERE r.development_id=j.development_id AND r.status='running') ORDER BY j.created_at FOR UPDATE SKIP LOCKED LIMIT 1) RETURNING *;END $$;
CREATE FUNCTION public.development_storia_photo_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d uuid;BEGIN d=CASE WHEN TG_OP='DELETE' THEN OLD.development_id ELSE NEW.development_id END;IF EXISTS(SELECT 1 FROM public.development_portal_publications WHERE development_id=d AND desired_active) THEN PERFORM public.queue_storia_development(d,'publish',auth.uid());END IF;RETURN NULL;END $$;
CREATE TRIGGER development_storia_photo_change AFTER INSERT OR UPDATE OR DELETE ON public.development_images FOR EACH ROW EXECUTE FUNCTION public.development_storia_photo_change();